        setTimeout(() => {
          // eslint-disable-next-line n/no-process-exit
          process.exit(harnessStatus.status === 0 ? 0 : 1)
        }, 50)
      } else {
        // eslint-disable-next-line n/no-process-exit
        process.exit(harnessStatus.status === 0 ? 0 : 1)
      }
    })
  })
}

