'use strict'
const ROOT = '/tmp/cxbench-undici/f3cbe48670-none'
const { createSecureServer } = require('node:http2')
const crypto = require('node:crypto')
const { WebSocketServer, WebSocket: WSWebsocket } = require(ROOT + '/node_modules/ws')
const { key, cert } = require(ROOT + '/node_modules/@metcoder95/https-pem')
const { uid } = require(ROOT + '/lib/web/websocket/constants')

function createH2WsServer (onConnection, { sendAccept = true } = {}) {
  const server = createSecureServer({ cert, key, settings: { enableConnectProtocol: true } })
  const wsServer = new WebSocketServer({ noServer: true })
  server.on('stream', (stream, headers) => {
    const respHeaders = { ':status': 200 }
    if (sendAccept) {
      respHeaders['sec-websocket-accept'] = crypto.hash('sha1', String(headers['sec-websocket-key']) + uid, 'base64')
    }
    stream.respond(respHeaders)
    const ws = new WSWebsocket(null, null, { autoPong: true })
    ws.setSocket(stream, Buffer.alloc(0), { maxPayload: 104857600, skipUTF8Validation: false })
    wsServer.emit('connection', ws, stream)
  })
  wsServer.on('connection', onConnection)
  return { server, wsServer }
}

module.exports = { createH2WsServer }
